/**
 * Check shell copy parity without claiming linguistic quality. This catches the easy-to-miss
 * cases where a newly added UI state is blank in a locale or drops an interpolation token.
 */
export function auditRespondentLocales(): string[] {
  const english = MESSAGES["en-AU"] as Record<string, string>;
  const issues: string[] = [];
  const placeholders = (value: string) => [...value.matchAll(/\{([a-zA-Z]+)\}/g)].map((match) => match[1]).sort();
  for (const locale of RESPONDENT_LOCALES) {
    const messages = MESSAGES[locale] as Record<string, string>;
    for (const key of Object.keys(english)) {
      const message = messages[key];
      if (typeof message !== "string" || message.trim() === "") {
        issues.push(`${locale}.${key} is missing or empty`);
      } else {
        // A one-item form may spell out "one" in the translated copy instead of printing {count}.
        const allowedOneCountOmission = key.endsWith("One");
        const localized = placeholders(message).filter((name) => !(allowedOneCountOmission && name === "count"));
        const reference = placeholders(english[key]).filter((name) => !(allowedOneCountOmission && name === "count"));
        if (JSON.stringify(localized) !== JSON.stringify(reference)) {
          issues.push(`${locale}.${key} has different interpolation placeholders`);
        }
      }
    }
    const issueMessages = REPEAT_ISSUE_MESSAGES[locale];
    for (const key of Object.keys(REPEAT_ISSUE_MESSAGES["en-AU"])) {
      if (!Object.hasOwn(issueMessages, key) || !issueMessages[key]?.trim()) issues.push(`${locale}.repeatIssue.${key} is missing or empty`);
    }
    const repeatEnglish = REPEAT_BRIDGE_MESSAGES["en-AU"];
    const repeatLocalized = REPEAT_BRIDGE_MESSAGES[locale];
    for (const key of Object.keys(repeatEnglish)) {
      const localizedMessage = repeatLocalized[key];
      if (!localizedMessage?.trim()) issues.push(`${locale}.${key} is missing or empty`);
      else if (JSON.stringify(placeholders(localizedMessage)) !== JSON.stringify(placeholders(repeatEnglish[key]!))) {
        issues.push(`${locale}.${key} has different interpolation placeholders`);
      }
    }
  }
  return issues;
}

export function isRespondentLocale(value: unknown): value is RespondentLocale {
  return typeof value === "string" && (RESPONDENT_LOCALES as readonly string[]).includes(value);
}

export function resolveRespondentLocale(acceptLanguage?: string | null, savedLocale?: string | null): RespondentLocale {
  if (isRespondentLocale(savedLocale)) return savedLocale;
  const preferences = (acceptLanguage ?? "").split(",").map((part, index) => {
    const [tag, ...parameters] = part.split(";");
    const quality = parameters.map((value) => value.trim().match(/^q=(0(?:\.\d{0,3})?|1(?:\.0{0,3})?)$/i)?.[1]).find(Boolean);
    return { tag: tag.trim().toLowerCase(), quality: quality === undefined ? 1 : Number(quality), index };
  }).filter((item) => item.quality > 0).sort((a, b) => b.quality - a.quality || a.index - b.index);
  for (const { tag: preference } of preferences) {
    if (preference === "vi" || preference.startsWith("vi-")) return "vi";
    if (preference === "es" || preference.startsWith("es-")) return "es";
    if (preference === "ar" || preference.startsWith("ar-")) return "ar";
    if (preference === "en" || preference.startsWith("en-")) return "en-AU";
  }
  return "en-AU";
}

export function respondentMessage(locale: RespondentLocale, key: RespondentMessage, values: Record<string, string | number> = {}): string {
  const localeMessages = MESSAGES[locale] as Record<string, string>;
  if (locale === "ar" && typeof values.count === "number") {
    const category = new Intl.PluralRules(locale).select(values.count);
    const pluralKey = `${key}${category[0].toUpperCase()}${category.slice(1)}`;
    if (pluralKey in localeMessages) {
      return localeMessages[pluralKey].replace(/\{([a-zA-Z]+)\}/g, (_, name: string) => {
        const value = values[name];
        return typeof value === "number" ? new Intl.NumberFormat(locale).format(value) : String(value ?? "");
      });
    }
  }
  const template = localeMessages[key] ?? MESSAGES["en-AU"][key];
  if (values.count === 1 && `${key}One` in MESSAGES[locale]) {
    const singular = MESSAGES[locale] as Record<string, string>;
    return singular[`${key}One`].replace(/\{([a-zA-Z]+)\}/g, (_, name: string) => {
      const value = values[name];
      return typeof value === "number" ? new Intl.NumberFormat(locale).format(value) : String(value ?? "");
    });
  }
  return template.replace(/\{([a-zA-Z]+)\}/g, (_, name: string) => {
    const value = values[name];
    return typeof value === "number" ? new Intl.NumberFormat(locale).format(value) : String(value ?? "");
  });
}

/** Keep dynamic string values available as isolated DOM runs for mixed-direction shell text. */
export function respondentMessageParts(locale: RespondentLocale, key: RespondentMessage, values: Record<string, string | number> = {}): ({ kind: "text"; text: string } | { kind: "isolate"; text: string })[] {
  const isolated = new Map<number, string>();
  const templated: Record<string, string | number> = { ...values };
  let index = 0;
  for (const [name, value] of Object.entries(values)) {
    if (typeof value !== "string") continue;
    const token = `\uE000kqa${index}\uE001`;
    isolated.set(index, value);
    templated[name] = token;
    index += 1;
  }
  const rendered = respondentMessage(locale, key, templated);
  const parts: ({ kind: "text"; text: string } | { kind: "isolate"; text: string })[] = [];
  const tokenPattern = /\uE000kqa(\d+)\uE001/g;
  let cursor = 0;
  for (const match of rendered.matchAll(tokenPattern)) {
    const start = match.index ?? 0;
    if (start > cursor) parts.push({ kind: "text", text: rendered.slice(cursor, start) });
    const value = isolated.get(Number(match[1]));
    if (value !== undefined) parts.push({ kind: "isolate", text: value });
    cursor = start + match[0].length;
  }
  if (cursor < rendered.length || !parts.length) parts.push({ kind: "text", text: rendered.slice(cursor) });
  return parts;
}

export function respondentTime(locale: RespondentLocale, date: Date): string {
  return new Intl.DateTimeFormat(locale, { hour: "numeric", minute: "2-digit" }).format(date);
}

/** Return complete localized bridge messages used for survee-generated controls inside the isolated frame. */
export function respondentBridgeMessages(locale: RespondentLocale): Record<string, string> {
  const messages = MESSAGES[locale];
  return {
    ...REPEAT_BRIDGE_MESSAGES[locale],
    rankMoveUp: respondentMessage(locale, "moveUp"),
    rankMoveDown: respondentMessage(locale, "moveDown"),
    rankConfirm: respondentMessage(locale, "useOrder"),
    rankPosition: messages.rankPosition,
    browseAnswered: messages.browseAnswered,
    rankMoveLabel: messages.rankMoveLabel,
    rankUseLabel: messages.rankUseLabel,
    rankError: respondentMessage(locale, "rankError"),
    exclusiveError: respondentMessage(locale, "exclusiveError"),
    maxSelections: messages.selectionMax,
    maxSelectionsOne: messages.maxSelectionsOne,
    minSelections: messages.selectionMin,
    minSelectionsOne: messages.minSelectionsOne,
    exclusiveHelp: respondentMessage(locale, "selectionExclusive"),
    requiredError: respondentMessage(locale, "requiredError"),
    answerRetained: respondentMessage(locale, "hiddenQuestionsDescription"),
    lengthCount: messages.lengthCount,
    lengthLimitReached: respondentMessage(locale, "lengthLimitReached"),
    lengthOverLimit: respondentMessage(locale, "lengthOverLimit"),
    lengthApproaching: respondentMessage(locale, "lengthApproaching"),
    lengthReachedAnnouncement: respondentMessage(locale, "lengthReachedAnnouncement"),
    lengthExceededAnnouncement: respondentMessage(locale, "lengthExceededAnnouncement"),
    questionShown: messages.questionShown,
    questionHidden: messages.questionHidden,
    rankMoved: messages.rankMoved,
    rankChanged: messages.rankChanged,
    savedMaxSelections: messages.savedMaxSelections,
    removeChoices: messages.removeChoices,
    exclusiveSelected: messages.exclusiveSelected,
    exclusiveCleared: messages.exclusiveCleared,
  };
}

