const REPEAT_ISSUE_BOUNDS: Record<RespondentLocale, Record<string, string>> = {
  "en-AU": { min_rows: "Add at least {minimum} records.", max_rows: "Add no more than {maximum} records.", max_length: "Enter no more than {maximum} characters.", below_minimum: "Enter a number of at least {minimum}.", above_maximum: "Enter a number no greater than {maximum}.", expected_scale: "Choose a scale value from {minimum} to {maximum}.", outside_scale: "Choose a scale value from {minimum} to {maximum}.", below_minimum_selections: "Choose at least {minimum} options, or leave this question blank.", above_maximum_selections: "Choose no more than {maximum} options." },
  vi: { min_rows: "Thêm ít nhất {minimum} bản ghi.", max_rows: "Thêm không quá {maximum} bản ghi.", max_length: "Nhập không quá {maximum} ký tự.", below_minimum: "Nhập số lớn hơn hoặc bằng {minimum}.", above_maximum: "Nhập số nhỏ hơn hoặc bằng {maximum}.", expected_scale: "Chọn giá trị thang đo từ {minimum} đến {maximum}.", outside_scale: "Chọn giá trị thang đo từ {minimum} đến {maximum}.", below_minimum_selections: "Chọn ít nhất {minimum} lựa chọn, hoặc để trống câu hỏi này.", above_maximum_selections: "Chọn không quá {maximum} lựa chọn." },
  es: { min_rows: "Añade al menos {minimum} registros.", max_rows: "Añade como máximo {maximum} registros.", max_length: "Introduce como máximo {maximum} caracteres.", below_minimum: "Introduce un número igual o superior a {minimum}.", above_maximum: "Introduce un número igual o inferior a {maximum}.", expected_scale: "Elige un valor de escala entre {minimum} y {maximum}.", outside_scale: "Elige un valor de escala entre {minimum} y {maximum}.", below_minimum_selections: "Elige al menos {minimum} opciones, o deja esta pregunta en blanco.", above_maximum_selections: "Elige como máximo {maximum} opciones." },
  ar: { min_rows: "أضف {minimum} من السجلات على الأقل.", max_rows: "أضف {maximum} من السجلات على الأكثر.", max_length: "أدخل {maximum} من الأحرف على الأكثر.", below_minimum: "أدخل رقمًا لا يقل عن {minimum}.", above_maximum: "أدخل رقمًا لا يزيد عن {maximum}.", expected_scale: "اختر قيمة للمقياس من {minimum} إلى {maximum}.", outside_scale: "اختر قيمة للمقياس من {minimum} إلى {maximum}.", below_minimum_selections: "اختر {minimum} خيارات على الأقل، أو اترك هذا السؤال فارغًا.", above_maximum_selections: "اختر {maximum} خيارات على الأكثر." },
};

export function respondentRepeatIssue(locale: RespondentLocale, issue?: RespondentRepeatIssue): string {
  const messages = REPEAT_ISSUE_MESSAGES[locale];
  const code = issue?.code;
  if (!code || !Object.hasOwn(messages, code)) return messages.generic;
  const bounds = REPEAT_ISSUE_BOUNDS[locale];
  if (!Object.hasOwn(bounds, code)) return messages[code];
  const template = bounds[code];
  const names = [...template.matchAll(/\{(minimum|maximum)\}/g)].map((match) => match[1]);
  if (names.some((name) => typeof issue?.params?.[name] !== "number" || !Number.isFinite(issue.params[name]))) return messages.generic;
  const format = new Intl.NumberFormat(locale);
  return template.replace(/\{(minimum|maximum)\}/g, (_, name: string) => format.format(issue!.params![name]));
}
